destinations.call:
getAthleteProfile(uid)
      .then((existing) => {
        if (!active) return;
        if (!existing) { router.replace('/athlete/profile'); return; }
        setProfile(existing);
      })
      .catch(() => {})

controls.handler:
{async () => {
        setSharing(true); setShareError(false);
        try { await Share.share({ message: sessionReport(session, readings) }); }
        catch { setShareError(true); }
        finally { setSharing(false); }
      }}

{async () => {
          setEnding(true);
          setEndError(false);
          try { await endSession(session); }
          catch { setEndError(true); }
          finally { setEnding(false); }
        }}

{async () => {
            setAcking(true);
            setError(false);
            try { await acknowledgeReading(session, latest); }
            catch { setError(true); }
            finally { setAcking(false); }
          }}

{() => {
              setNow(Date.now());
              if (coolStart === null || coolStop !== null) { setCoolStart(Date.now()); setCoolStop(null); } else setCoolStop(Date.now());
            }}
